if(SolarSystem.getFlagPlanets()) {
    core.debug("Planets are visible");
} else {
    SolarSystem.setFlagPlanets(true);
}

// Hide all planets
SolarSystem.setFlagPlanets(false);

// Show all planets
SolarSystem.setFlagPlanets(true);

// Toggle planet visibility
var current = SolarSystem.getFlagPlanets();
SolarSystem.setFlagPlanets(!current);

// Show planet hints
SolarSystem.setFlagHints(true);

// Hide planet hints
SolarSystem.setFlagHints(false);

// Show planet names
SolarSystem.setFlagLabels(true);

// Hide planet names
SolarSystem.setFlagLabels(false);

// Show labels for bright planets only
SolarSystem.setLabelsAmount(2.0);

// Show labels for all planets
SolarSystem.setLabelsAmount(8.0);

// Show planet orbits
SolarSystem.setFlagOrbits(true);

// Hide planet orbits
SolarSystem.setFlagOrbits(false);

// Show planet motion trails
SolarSystem.setFlagTrails(true);

// Hide trails
SolarSystem.setFlagTrails(false);

// Reset trails
SolarSystem.recreateTrails();

// Enable selection pointer
SolarSystem.setFlagPointer(true);

// Disable selection pointer
SolarSystem.setFlagPointer(false);

if(SolarSystem.getFlagMarkers()) {
    core.debug("Minor body markers are visible");
}

// Show asteroid and comet markers
SolarSystem.setFlagMarkers(true);

// Hide minor body markers
SolarSystem.setFlagMarkers(false);

if(SolarSystem.getFlagLightTravelTime()) {
    core.debug("Light travel time correction is active");
}

// Enable realistic light travel time
SolarSystem.setFlagLightTravelTime(true);

// Disable for geometric positions
SolarSystem.setFlagLightTravelTime(false);

// Enable Moon halo
SolarSystem.setFlagDrawMoonHalo(true);

// Disable Moon halo
SolarSystem.setFlagDrawMoonHalo(false);

if(SolarSystem.getFlagIsolatedTrails()) {
    core.debug("Only selected objects show trails");
}

// Show trails only for selected planets
SolarSystem.setFlagIsolatedTrails(true);

// Show trails for all planets
SolarSystem.setFlagIsolatedTrails(false);

if(SolarSystem.getFlagIsolatedOrbits()) {
    core.debug("Only selected objects show orbits");
}

// Show orbit only for selected planet
SolarSystem.setFlagIsolatedOrbits(true);

// Show all planet orbits
SolarSystem.setFlagIsolatedOrbits(false);

if(SolarSystem.getFlagPlanetsOrbits()) {
    core.debug("Major planet orbits are visible");
}

// Show all major planet orbits
SolarSystem.setFlagPlanetsOrbits(true);

// Hide major planet orbits
SolarSystem.setFlagPlanetsOrbits(false);

// Show orbits only for major planets
SolarSystem.setFlagPlanetsOrbitsOnly(true);

// Show orbits for all objects
SolarSystem.setFlagPlanetsOrbitsOnly(false);

// Show planet and moon orbits
SolarSystem.setFlagOrbitsWithMoons(true);
SolarSystem.setFlagOrbits(true);

// Show only planet orbits
SolarSystem.setFlagOrbitsWithMoons(false);

// After editing ssystem_minor.ini
SolarSystem.reloadPlanets();
core.debug("Solar system data reloaded");

// Reset trails to start fresh
SolarSystem.recreateTrails();
core.debug("Trails recreated");

// Reset Mars texture
SolarSystem.resetTextures("Mars");

// Reset all planet textures
SolarSystem.resetTextures("");

var core = StelApp.getCore();
var eclipseInfo = SolarSystem.getSolarEclipseFactor(core);
var factor = eclipseInfo.first;
var planet = eclipseInfo.second;
core.debug("Solar eclipse factor: " + factor);
if(factor > 0.9) {
    core.debug("Near total eclipse!");
}

var mars = SolarSystem.searchByEnglishName("Mars");
if(mars) {
    core.debug("Found Mars");
    core.moveToObject(mars.getEnglishName(), 2);
}

var ceres = SolarSystem.searchMinorPlanetByEnglishName("Ceres");
if(ceres) {
    core.debug("Found Ceres dwarf planet");
}

var planets = SolarSystem.getAllPlanetEnglishNames();
core.debug("Total planets: " + planets.length);
for(var i=0; i<planets.length; i++) {
    core.debug(planets[i]);
}

var marsMag = SolarSystem.getPlanetVMagnitude("Mars");
core.debug("Mars magnitude: " + marsMag);

var venusMag = SolarSystem.getPlanetVMagnitude("Venus", true);
core.debug("Venus magnitude with extinction: " + venusMag);

var elong = SolarSystem.getElongationForPlanet("Venus");
var elongDeg = elong * 180 / Math.PI;
core.debug("Venus elongation: " + elongDeg.toFixed(1) + "°");

var phaseAngle = SolarSystem.getPhaseAngleForPlanet("Moon");
var phaseAngleDeg = phaseAngle * 180 / Math.PI;
core.debug("Moon phase angle: " + phaseAngleDeg.toFixed(1) + "°");

var moonPhase = SolarSystem.getPhaseForPlanet("Moon");
core.debug("Moon phase: " + (moonPhase * 100).toFixed(1) + "%");

var venusPhase = SolarSystem.getPhaseForPlanet("Venus");
core.debug("Venus illuminated: " + (venusPhase * 100).toFixed(1) + "%");

// Get all solar system objects
var allObjects = SolarSystem.getObjectsList("all");

// Get only asteroids
var asteroids = SolarSystem.getObjectsList("asteroid");

// Get only comets
var comets = SolarSystem.getObjectsList("comet");

core.debug("Asteroids count: " + asteroids.length);

// Enlarge the Moon for better visibility
SolarSystem.setFlagMoonScale(true);
SolarSystem.setMoonScale(4.0);

// Use real Moon size
SolarSystem.setFlagMoonScale(false);

// Make Moon 4 times larger
SolarSystem.setMoonScale(4.0);
SolarSystem.setFlagMoonScale(true);

if(SolarSystem.getFlagDynamicMoonScale()) {
    core.debug("Dynamic Moon scaling is active");
}

// Enable dynamic Moon scaling
SolarSystem.setFlagDynamicMoonScale(true);
SolarSystem.setFlagMoonScale(true);
SolarSystem.setMoonScale(4.0);
SolarSystem.setMoonScaleMinFov(10.0);
SolarSystem.setMoonScaleMaxFov(90.0);

// Enlarge minor bodies for visibility
SolarSystem.setFlagMinorBodyScale(true);
SolarSystem.setMinorBodyScale(10.0);

// Use real sizes
SolarSystem.setFlagMinorBodyScale(false);

// Make asteroids 10 times larger
SolarSystem.setMinorBodyScale(10.0);
SolarSystem.setFlagMinorBodyScale(true);

// Enlarge planets for visibility
SolarSystem.setFlagPlanetScale(true);
SolarSystem.setPlanetScale(150.0);

// Use real planet sizes
SolarSystem.setFlagPlanetScale(false);

// Enlarge the Sun
SolarSystem.setFlagSunScale(true);
SolarSystem.setSunScale(4.0);

// Use real Sun size
SolarSystem.setFlagSunScale(false);

if(SolarSystem.getFlagEphemerisLine()) {
    core.debug("Ephemeris path line is visible");
}

if(SolarSystem.getFlagEphemerisNow()) {
    core.debug("Current position marker is visible");
}

// Set labels to white
var white = core.vec3f(1.0, 1.0, 1.0);
SolarSystem.setLabelsColor(white);

// Set labels to light blue
var lightBlue = core.vec3f(0.5, 0.7, 1.0);
SolarSystem.setLabelsColor(lightBlue);

// Set orbits to cyan
var cyan = core.vec3f(0.0, 0.8, 0.9);
SolarSystem.setOrbitsColor(cyan);

// Show only brighter minor bodies
SolarSystem.setMarkerMagThreshold(12.0);

// Show all minor bodies (faintest)
SolarSystem.setMarkerMagThreshold(20.0);

// Use modern Mallama 2018 algorithm
SolarSystem.setApparentMagnitudeAlgorithmOnEarth("Mallama2018");

// Use classic Mueller 1893 (visual magnitudes)
SolarSystem.setApparentMagnitudeAlgorithmOnEarth("Mueller1893");

// Thicker orbits for better visibility
SolarSystem.setOrbitsThickness(2);

// Thin elegant orbits
SolarSystem.setOrbitsThickness(1);

// Longer trails
SolarSystem.setMaxTrailPoints(10000);

// Shorter trails for performance
SolarSystem.setMaxTrailPoints(1000);

if(SolarSystem.getFlagPermanentOrbits()) {
    core.debug("Orbits visible even when planets are off-screen");
}

// Color orbits by object groups
SolarSystem.setOrbitColorStyle("groups");

// All orbits same color
SolarSystem.setOrbitColorStyle("one_color");

// Always show solar corona
SolarSystem.setFlagPermanentSolarCorona(true);

// Only during eclipses
SolarSystem.setFlagPermanentSolarCorona(false);
